    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def to_pos(x, default=0):
        if isinstance(x, (list, tuple)) and len(x) >= 2:
            try:
                return int(x[0]), int(x[1])
            except Exception:
                return default, default
        return default, default

    def get_pos(obs, keys, default=(0, 0)):
        for k in keys:
            p = obs.get(k)
            if p is not None:
                return to_pos(p, default[0])
        return default

    def step_toward(src, dst):
        return [clamp_step(dst[0] - src[0]), clamp_step(dst[1] - src[1])]

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def farthest_corner(pos, w, h):
        corners = [(0, 0), (0, max(0, h - 1)), (max(0, w - 1), 0), (max(0, w - 1), max(0, h - 1))]
        best = corners[0]
        best_d = manhattan(pos, best)
        for c in corners[1:]:
            d = manhattan(pos, c)
            if d > best_d:
                best, best_d = c, d
        return best

